  "app/src/main/res/values/strings.xml": { encoding: "utf8", content: "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<resources>\n    <string name=\"app_name\">{{projectName}}</string>\n    <string name=\"home_subtitle\">A native Android app built with Kotlin and Jetpack Compose.</string>\n    <string name=\"home_card_title\">Your starting point</string>\n    <string name=\"home_taps\">Taps: %1$d</string>\n    <string name=\"home_action\">Tap the button</string>\n</resources>\n" },
