  "app/src/main/res/xml/backup_rules.xml": { encoding: "utf8", content: "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<!-- Default privacy policy for SDK 26–30: do not export app data. -->\n<full-backup-content>\n    <exclude domain=\"root\" path=\".\" />\n    <exclude domain=\"device_root\" path=\".\" />\n    <exclude domain=\"external\" path=\".\" />\n</full-backup-content>\n" },
  "app/src/main/res/xml/data_extraction_rules.xml": { encoding: "utf8", content: "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<!-- On API 31+, cloud and device transfer must both be explicitly restricted. -->\n<data-extraction-rules>\n    <cloud-backup>\n        <exclude domain=\"root\" path=\".\" />\n        <exclude domain=\"device_root\" path=\".\" />\n        <exclude domain=\"external\" path=\".\" />\n    </cloud-backup>\n    <device-transfer>\n        <exclude domain=\"root\" path=\".\" />\n        <exclude domain=\"device_root\" path=\".\" />\n        <exclude domain=\"external\" path=\".\" />\n    </device-transfer>\n</data-extraction-rules>\n" },
  "app/src/test/java/{{packagePath}}/GreetingTest.kt": { encoding: "utf8", content: "package {{packageName}}.ui\n\nimport org.junit.Assert.assertEquals\nimport org.junit.Test\n\nclass GreetingTest {\n    @Test\n    fun `zero taps shows the initial message`() {\n        assertEquals(\"Ready to build.\", greetingMessage(0))\n    }\n\n    @Test\n    fun `one tap is reported in singular`() {\n        assertEquals(\"You tapped once.\", greetingMessage(1))\n    }\n\n    @Test\n    fun `many taps are reported with the count`() {\n        assertEquals(\"You tapped 7 times.\", greetingMessage(7))\n    }\n\n    @Test\n    fun `negative values are treated as zero`() {\n        assertEquals(\"Ready to build.\", greetingMessage(-3))\n    }\n}\n" },
  "build.gradle.kts": { encoding: "utf8", content: "buildscript {\n    repositories {\n        google()\n        mavenCentral()\n    }\n    dependencies {\n        // AGP 9 ships built-in Kotlin support. This upgrades the Kotlin toolchain\n        // used by AGP and by the Compose compiler to the pinned project version.\n        classpath(\"org.jetbrains.kotlin:kotlin-gradle-plugin:{{kotlinVersion}}\")\n    }\n}\n\nplugins {\n    alias(libs.plugins.android.application) apply false\n    alias(libs.plugins.compose.compiler) apply false\n    // @launchbed-slot root-plugins\n}\n" },
  "gradle.properties": { encoding: "utf8", content: "org.gradle.jvmargs=-Xmx2048m -Dfile.encoding=UTF-8\norg.gradle.parallel=true\norg.gradle.caching=true\nandroid.nonTransitiveRClass=true\n" },
  "gradle/libs.versions.toml": { encoding: "utf8", content: "[versions]\nagp = \"{{agpVersion}}\"\nkotlin = \"{{kotlinVersion}}\"\ncomposeBom = \"{{composeBomVersion}}\"\nactivityCompose = \"{{activityComposeVersion}}\"\njunit = \"{{junitVersion}}\"\n\n[libraries]\nandroidx-activity-compose = { module = \"androidx.activity:activity-compose\", version.ref = \"activityCompose\" }\nandroidx-compose-bom = { module = \"androidx.compose:compose-bom\", version.ref = \"composeBom\" }\nandroidx-compose-material3 = { module = \"androidx.compose.material3:material3\" }\nandroidx-compose-ui = { module = \"androidx.compose.ui:ui\" }\nandroidx-compose-ui-graphics = { module = \"androidx.compose.ui:ui-graphics\" }\nandroidx-compose-ui-tooling = { module = \"androidx.compose.ui:ui-tooling\" }\nandroidx-compose-ui-tooling-preview = { module = \"androidx.compose.ui:ui-tooling-preview\" }\njunit = { module = \"junit:junit\", version.ref = \"junit\" }\n\n[plugins]\nandroid-application = { id = \"com.android.application\", version.ref = \"agp\" }\ncompose-compiler = { id = \"org.jetbrains.kotlin.plugin.compose\", version.ref = \"kotlin\" }\n" },
