  "foundation/ui-components.txt": "package {{packageName}}.foundation.ui\n\nimport androidx.compose.foundation.layout.Arrangement\nimport androidx.compose.foundation.layout.Column\nimport androidx.compose.foundation.layout.Row\nimport androidx.compose.foundation.layout.fillMaxWidth\nimport androidx.compose.foundation.layout.padding\nimport androidx.compose.material3.AlertDialog\nimport androidx.compose.material3.CircularProgressIndicator\nimport androidx.compose.material3.MaterialTheme\nimport androidx.compose.material3.Text\nimport androidx.compose.material3.TextButton\nimport androidx.compose.runtime.Composable\nimport androidx.compose.ui.Alignment\nimport androidx.compose.ui.Modifier\nimport androidx.compose.ui.semantics.contentDescription\nimport androidx.compose.ui.semantics.semantics\nimport {{packageName}}.ui.theme.Spacing\n\n@Composable\nfun AppLoading(modifier: Modifier = Modifier, label: String = \"Loading\") {\n    Column(\n        modifier = modifier.semantics { contentDescription = label },\n        horizontalAlignment = Alignment.CenterHorizontally,\n        verticalArrangement = Arrangement.Center,\n    ) {\n        CircularProgressIndicator()\n        Text(text = label, modifier = Modifier.padding(top = Spacing.sm))\n    }\n}\n\n@Composable\nfun AppEmptyState(title: String, message: String, modifier: Modifier = Modifier) {\n    Column(\n        modifier = modifier,\n        horizontalAlignment = Alignment.CenterHorizontally,\n        verticalArrangement = Arrangement.Center,\n    ) {\n        Text(text = title, style = MaterialTheme.typography.titleMedium)\n        Text(text = message, color = MaterialTheme.colorScheme.onSurfaceVariant)\n    }\n}\n\n@Composable\nfun AppErrorState(message: String, onRetry: (() -> Unit)? = null, modifier: Modifier = Modifier) {\n    Column(modifier = modifier, horizontalAlignment = Alignment.CenterHorizontally) {\n        Text(text = message, color = MaterialTheme.colorScheme.error)\n        if (onRetry != null) {\n            TextButton(onClick = onRetry) { Text(\"Retry\") }\n        }\n    }\n}\n\n@Composable\nfun AppSectionHeader(title: String, modifier: Modifier = Modifier) {\n    Text(\n        text = title,\n        style = MaterialTheme.typography.titleSmall,\n        color = MaterialTheme.colorScheme.primary,\n        modifier = modifier.padding(vertical = Spacing.sm),\n    )\n}\n\n@Composable\nfun AppInfoCard(title: String, value: String, modifier: Modifier = Modifier) {\n    androidx.compose.material3.Card(modifier = modifier) {\n        Column(modifier = Modifier.padding(Spacing.md)) {\n            Text(text = title, style = MaterialTheme.typography.labelMedium)\n            Text(text = value, style = MaterialTheme.typography.headlineSmall)\n        }\n    }\n}\n\n@Composable\nfun AppFormField(\n    value: String,\n    onValueChange: (String) -> Unit,\n    label: String,\n    error: String? = null,\n    modifier: Modifier = Modifier,\n) {\n    androidx.compose.material3.OutlinedTextField(\n        value = value,\n        onValueChange = onValueChange,\n        label = { Text(label) },\n        isError = error != null,\n        supportingText = { error?.let { Text(it) } },\n        modifier = modifier,\n    )\n}\n\n@Composable\nfun AppConfirmationDialog(\n    title: String,\n    message: String,\n    confirmLabel: String = \"Confirm\",\n    dismissLabel: String = \"Cancel\",\n    onConfirm: () -> Unit,\n    onDismiss: () -> Unit,\n) {\n    AlertDialog(\n        onDismissRequest = onDismiss,\n        confirmButton = { TextButton(onClick = onConfirm) { Text(confirmLabel) } },\n        dismissButton = { TextButton(onClick = onDismiss) { Text(dismissLabel) } },\n        title = { Text(title) },\n        text = { Text(message) },\n    )\n}\n",
  "storage/room-androidtest-deps.txt": "    androidTestImplementation(libs.androidxtestextjunit)\n",
  "storage/room-app-database.txt": "package {{packageName}}.data.local\n\nimport android.content.Context\nimport androidx.room.Database\nimport androidx.room.Room\nimport androidx.room.RoomDatabase\n\n@Database(\n    entities = [NoteEntity::class],\n    version = 1,\n    exportSchema = true,\n)\nabstract class AppDatabase : RoomDatabase() {\n    abstract fun noteDao(): NoteDao\n\n    companion object {\n        @Volatile\n        private var instance: AppDatabase? = null\n\n        fun getInstance(context: Context): AppDatabase =\n            instance ?: synchronized(this) {\n                instance ?: Room.databaseBuilder(\n                    context.applicationContext,\n                    AppDatabase::class.java,\n                    \"notes.db\",\n                ).build().also { instance = it }\n            }\n\n        internal fun replaceForTesting(database: AppDatabase?) {\n            instance = database\n        }\n    }\n}\n",
