  "storage/room-note-dao-test.txt": "package {{packageName}}.data.local\n\nimport android.content.Context\nimport androidx.room.Room\nimport androidx.test.core.app.ApplicationProvider\nimport androidx.test.ext.junit.runners.AndroidJUnit4\nimport kotlinx.coroutines.CompletableDeferred\nimport kotlinx.coroutines.async\nimport kotlinx.coroutines.flow.onEach\nimport kotlinx.coroutines.flow.take\nimport kotlinx.coroutines.flow.toList\nimport kotlinx.coroutines.runBlocking\nimport kotlinx.coroutines.withTimeout\nimport org.junit.After\nimport org.junit.Assert.assertEquals\nimport org.junit.Assert.assertTrue\nimport org.junit.Before\nimport org.junit.Test\nimport org.junit.runner.RunWith\n\n@RunWith(AndroidJUnit4::class)\nclass NoteDaoTest {\n    private lateinit var database: AppDatabase\n    private lateinit var dao: NoteDao\n\n    @Before\n    fun createDatabase() {\n        val context = ApplicationProvider.getApplicationContext<Context>()\n        database = Room.inMemoryDatabaseBuilder(context, AppDatabase::class.java)\n            .allowMainThreadQueries()\n            .build()\n        dao = database.noteDao()\n    }\n\n    @After\n    fun closeDatabase() {\n        database.close()\n    }\n\n    @Test\n    fun insertAndRetrieve() = runBlocking {\n        val id = dao.insert(NoteEntity(title = \"title\", content = \"content\", updatedAt = 1L))\n        val note = dao.getById(id)\n        assertEquals(\"title\", note?.title)\n        assertEquals(\"content\", note?.content)\n    }\n\n    @Test\n    fun updateNote() = runBlocking {\n        val id = dao.insert(NoteEntity(title = \"before\", content = \"before\", updatedAt = 1L))\n        dao.update(NoteEntity(id = id, title = \"after\", content = \"after\", updatedAt = 2L))\n        assertEquals(\"after\", dao.getById(id)?.title)\n    }\n\n    @Test\n    fun deleteNote() = runBlocking {\n        val id = dao.insert(NoteEntity(title = \"title\", content = \"content\", updatedAt = 1L))\n        dao.delete(NoteEntity(id = id, title = \"title\", content = \"content\", updatedAt = 1L))\n        assertEquals(null, dao.getById(id))\n    }\n    @Test\n    fun observesInsertedNotes() = runBlocking {\n        val initialObserved = CompletableDeferred<Unit>()\n        val observations = async {\n            withTimeout(10_000L) {\n                dao.observeAll()\n                    .onEach { if (it.isEmpty()) initialObserved.complete(Unit) }\n                    .take(2)\n                    .toList()\n            }\n        }\n        withTimeout(10_000L) { initialObserved.await() }\n        dao.insert(NoteEntity(title = \"live\", content = \"value\", updatedAt = 1L))\n        val values = observations.await()\n        assertTrue(values.first().isEmpty())\n        assertEquals(\"live\", values.last().single().title)\n    }\n\n    @Test\n    fun fileDatabasePersistsAcrossCloseAndReopen() = runBlocking {\n        val context = ApplicationProvider.getApplicationContext<Context>()\n        val name = \"launchbed-test-${java.util.UUID.randomUUID()}.db\"\n        var fileDatabase: AppDatabase? = null\n        try {\n            fileDatabase = Room.databaseBuilder(context, AppDatabase::class.java, name).build()\n            val id = fileDatabase.noteDao().insert(\n                NoteEntity(title = \"persistent\", content = \"saved\", updatedAt = 1L),\n            )\n            fileDatabase.close()\n            fileDatabase = Room.databaseBuilder(context, AppDatabase::class.java, name).build()\n            assertEquals(\"persistent\", fileDatabase.noteDao().getById(id)?.title)\n        } finally {\n            fileDatabase?.close()\n            context.deleteDatabase(name)\n        }\n    }\n\n}\n",
  "storage/room-note-dao.txt": "package {{packageName}}.data.local\n\nimport androidx.room.Dao\nimport androidx.room.Delete\nimport androidx.room.Insert\nimport androidx.room.OnConflictStrategy\nimport androidx.room.Query\nimport androidx.room.Update\nimport kotlinx.coroutines.flow.Flow\n\n@Dao\ninterface NoteDao {\n    @Insert(onConflict = OnConflictStrategy.REPLACE)\n    suspend fun insert(note: NoteEntity): Long\n\n    @Update\n    suspend fun update(note: NoteEntity)\n\n    @Delete\n    suspend fun delete(note: NoteEntity)\n\n    @Query(\"SELECT * FROM notes WHERE id = :id\")\n    suspend fun getById(id: Long): NoteEntity?\n\n    @Query(\"SELECT * FROM notes ORDER BY updatedAt DESC\")\n    fun observeAll(): Flow<List<NoteEntity>>\n}\n",
