  "ui/catalog-screen.txt": "package {{packageName}}.ui.catalog\n\nimport androidx.compose.foundation.layout.Arrangement\nimport androidx.compose.foundation.layout.Column\nimport androidx.compose.foundation.layout.PaddingValues\nimport androidx.compose.foundation.layout.fillMaxSize\nimport androidx.compose.foundation.layout.fillMaxWidth\nimport androidx.compose.foundation.layout.padding\nimport androidx.compose.foundation.lazy.LazyColumn\nimport androidx.compose.foundation.lazy.items\nimport androidx.compose.material3.Card\nimport androidx.compose.material3.MaterialTheme\nimport androidx.compose.material3.ExperimentalMaterial3Api\nimport androidx.compose.material3.OutlinedTextField\nimport androidx.compose.material3.Scaffold\nimport androidx.compose.material3.Text\nimport androidx.compose.material3.TopAppBar\nimport androidx.compose.runtime.Composable\nimport androidx.compose.runtime.getValue\nimport androidx.compose.runtime.mutableStateOf\nimport androidx.compose.runtime.remember\nimport androidx.compose.runtime.setValue\nimport androidx.compose.ui.Modifier\nimport {{packageName}}.ui.theme.Spacing\n\ndata class CatalogItem(val id: String, val title: String, val category: String)\n\nprivate val demoItems = listOf(\n    CatalogItem(\"1\", \"Compose toolkit\", \"UI\"),\n    CatalogItem(\"2\", \"Room storage\", \"Data\"),\n    CatalogItem(\"3\", \"Navigation\", \"Architecture\"),\n)\n\n@OptIn(ExperimentalMaterial3Api::class)\n@Composable\nfun CatalogScreen() {\n    var query by remember { mutableStateOf(\"\") }\n    val filtered = demoItems.filter {\n        it.title.contains(query, ignoreCase = true) || it.category.contains(query, ignoreCase = true)\n    }\n\n    Scaffold(topBar = { TopAppBar(title = { Text(\"Catalog\") }) }) { innerPadding ->\n        Column(\n            modifier = Modifier\n                .fillMaxSize()\n                .padding(innerPadding)\n                .padding(Spacing.lg),\n            verticalArrangement = Arrangement.spacedBy(Spacing.md),\n        ) {\n            OutlinedTextField(\n                value = query,\n                onValueChange = { query = it },\n                label = { Text(\"Search\") },\n                modifier = Modifier.fillMaxWidth(),\n            )\n            if (filtered.isEmpty()) {\n                Text(\"No items match your search.\", color = MaterialTheme.colorScheme.onSurfaceVariant)\n            } else {\n                LazyColumn(contentPadding = PaddingValues(vertical = Spacing.sm)) {\n                    items(filtered, key = { it.id }) { item ->\n                        Card(modifier = Modifier.fillMaxWidth().padding(vertical = Spacing.xs)) {\n                            Column(modifier = Modifier.padding(Spacing.md)) {\n                                Text(text = item.title, style = MaterialTheme.typography.titleMedium)\n                                Text(text = item.category, style = MaterialTheme.typography.bodySmall)\n                            }\n                        }\n                    }\n                }\n            }\n        }\n    }\n}\n",
  "ui/catalog-test.txt": "package {{packageName}}.ui.catalog\n\nimport androidx.compose.ui.test.assertIsDisplayed\nimport androidx.compose.ui.test.junit4.createComposeRule\nimport androidx.compose.ui.test.onNodeWithText\nimport org.junit.Rule\nimport org.junit.Test\nimport org.junit.runner.RunWith\nimport androidx.test.ext.junit.runners.AndroidJUnit4\n\n@RunWith(AndroidJUnit4::class)\nclass CatalogScreenTest {\n    @get:Rule val composeRule = createComposeRule()\n\n    @Test fun catalogShowsDemoItem() {\n        composeRule.setContent { CatalogScreen() }\n        composeRule.onNodeWithText(\"Compose toolkit\").assertIsDisplayed()\n    }\n\n    @Test fun catalogShowsEmptySearchState() {\n        composeRule.setContent { CatalogScreen() }\n        composeRule.onNodeWithText(\"Search\").assertIsDisplayed()\n    }\n}\n",
