  "ui/navigation-start-route.txt": "package {{packageName}}.ui.navigation\n\nimport androidx.compose.runtime.Composable\nimport androidx.navigation3.runtime.NavKey\n{{startRouteImports}}\n\ninternal fun MutableList<NavKey>.replaceRoot(destination: AppRoute) {\n    add(destination)\n    while (size > 1) {\n        removeAt(0)\n    }\n}\n\n@Composable\nfun rememberStartRoute(): AppRoute? {\n{{startRouteBody}}    return AppRoute.{{initialRoute}}\n}\n",
